/* edges details for region "measurement", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("measurement.edges",{"edges":{
"activation-energy:montecarlo":{"type":"connection","label":{"zh":"只有分布的尾部起作用","en":"Only the tail of a distribution matters"},"reason":{"zh":"反应速率由能量分布尾部那一小部分分子决定，估计稀有事件需要大量样本。","en":"The rate is set by the small tail of the energy distribution, and estimating a rare event takes a very large sample."},"source":"../chemistry/reactions/activation-energy/#step1"},
"attention-mechanism:llm-sampling":{"type":"connection","label":{"zh":"同一个 softmax","en":"the same softmax"},"reason":{"zh":"注意力权重和下一词概率都由 softmax 得到；温度相当于第 1 步锐度 β 的倒数。","en":"Attention weights and next-word probabilities both come from softmax; temperature acts as the inverse of the sharpness β in the attention page's step 1."},"source":"../computing/ml/llm-sampling/#step1"},
"averaging-leveling:bar-charts":{"type":"representation","label":{"zh":"同一个平均数的两种画法","en":"Two pictures of one mean"},"reason":{"zh":"倒水齐平与条形图上的平均线是同一件事：高出的部分正好补足不足的部分。","en":"Pouring until level and the mean line on a bar chart are the same fact: what sticks out exactly fills what falls short."},"source":"../math/data/averaging-leveling/#step1"},
"bar-charts:probability":{"type":"foundation","label":{"zh":"平均数是重心","en":"The mean is a balance point"},"reason":{"zh":"平均线使高出的总长等于不足的总长，这正是期望作为概率加权重心的最简单情形（各结果权重相同）。","en":"The mean line makes total excess equal total shortfall, the simplest case (equal weights) of expectation as a probability-weighted balance point."},"source":"../math/data/bar-charts/#step3"},
"base-rate-neglect:vaccinated-share-of-cases":{"type":"connection","label":{"zh":"基础比率","en":"Base rates"},"reason":{"zh":"第 5 章：病例里多数打过疫苗，是因为接种者本来就多得多，这是基础比率问题；“数字没有说谎，结论却错了”第 6 章用阳性检测讲了同一结构。","en":"Chapter 5: most cases are vaccinated because vaccinated people are far more numerous to begin with, a base-rate question; chapter 6 of Every Number Was True shows the same structure with a positive test."},"source":"../biology/body/how-vaccines-work/#ch5"},
"bayes:bandit-arms":{"type":"application","label":{"zh":"Beta 信念随观测更新","en":"Beta beliefs updated by observations"},"reason":{"zh":"汤普森采样用 Beta 分布表达对中奖率的信念，每次中奖或没中就更新一次，这是贝叶斯更新在决策里的用法。","en":"Thompson sampling uses a Beta distribution for the belief about the win rate and updates it after every win or loss, which is Bayesian updating used inside decisions."},"source":"../probability/stochastic/bandit-arms/#step3"},
"bayes:base-rate-neglect":{"type":"foundation","label":{"zh":"先验就是基础比率","en":"The prior is the base rate"},"reason":{"zh":"第 6 章说检测结果的含义取决于检测前有多常见，并把“第二次检测怎么改变判断”交给贝叶斯更新的第 1 步。","en":"Chapter 6 says a result’s meaning depends on how common the condition was before the test, and leaves “how a second test changes the judgement” to step 1 of Bayesian updating."},"source":"../probability/everyday/numbers-lie/#c6"},
"bayes:hypothesis-testing":{"type":"connection","label":{"zh":"两个不同的问题","en":"Two different questions"},"reason":{"zh":"p 值回答“若假设为真，数据这么极端的概率”；贝叶斯回答“给定数据，假设为真的概率”，需要先验。两者经常被混为一谈。","en":"A p-value answers “if the hypothesis is true, how probable is data this extreme”; Bayes answers “given the data, how probable is the hypothesis”, which needs a prior. The two are often confused."},"source":"../probability/inference/hypothesis-testing/#step5"},
"bayes:kalman":{"type":"application","label":{"zh":"在线性高斯条件下形成状态更新","en":"gives state updates under linear Gaussian assumptions"},"reason":{"zh":"在线性动态与观测模型、适当高斯先验和独立高斯噪声条件下，卡尔曼更新可用均值与协方差表示贝叶斯更新。","en":"With linear dynamics and measurements, an appropriate Gaussian prior and independent Gaussian noises, Kalman updates express Bayesian updating using means and covariances."},"source":"../signal/control/kalman/#step6"},
"bayes:mendelian-inheritance":{"type":"connection","label":{"zh":"看到表型后换分母","en":"Seeing the phenotype changes the denominator"},"reason":{"zh":"已知后代是显性表型，问它是杂合子的概率：先划掉不可能的 aa 格，再在剩下三格里数，得 2/3——这就是条件概率，也是贝叶斯更新最简单的样子。","en":"Given that an offspring shows the dominant trait, the chance it is heterozygous comes from striking out the impossible aa cell and counting among the remaining three: 2/3 — conditional probability, the simplest form of a Bayesian update."},"source":"../probability/basics/genetics-probability/#step3"},
"bayes:positive-predictive-value":{"type":"application","label":{"zh":"后验就是阳性预测值","en":"The posterior is the positive predictive value"},"reason":{"zh":"患病率是先验，灵敏度与特异度给出似然；看到阳性后用贝叶斯更新得到的后验，正是“阳性者里真患病的比例”。","en":"Prevalence is the prior and sensitivity and specificity supply the likelihoods; the posterior after seeing a positive result is exactly the share of positives who are truly ill."},"source":"../probability/inference/bayes-diagnostics/#step-posterior"},
"binomial-normal:condorcet-jury-theorem":{"type":"foundation","label":{"zh":"多数判对的概率是二项尾概率","en":"The majority’s accuracy is a binomial tail"},"reason":{"zh":"第 9 章的陪审团定理用二项分布的尾概率：每人对的概率 0.6 时，11 人多数判对 75%，101 人 98%。","en":"Chapter 9’s jury theorem is a binomial tail probability: with each voter right 60% of the time, a majority of 11 is right 75% of the time and of 101, 98%."},"source":"../society/civics/same-votes-different-winner/#ch9"},
"binomial-normal:gaussian":{"type":"connection","label":{"zh":"n 大时贴近正态","en":"Approaches the normal for large n"},"reason":{"zh":"二项柱状图在 n 大且 p 不太偏时贴近同均值同标准差的正态曲线，这是正态分布出现的一条最直观途径。","en":"For large n and a not-too-lopsided p the binomial bars hug the normal curve with the same mean and spread, one of the most visible routes by which the normal distribution appears."},"source":"../probability/basics/binomial-normal/#step3"},
"binomial-normal:variance":{"type":"application","label":{"zh":"方差 np(1−p)","en":"Variance np(1−p)"},"reason":{"zh":"二项分布是独立伯努利方差相加的实例：每次方差 p(1−p)，n 次相加得 np(1−p)。","en":"The binomial is an instance of independent variances adding: each trial has variance p(1−p), so n trials give np(1−p)."},"source":"../probability/basics/binomial-normal/#step2"},
"buffer-solution:titration-curves":{"type":"connection","label":{"zh":"缓冲区就是滴定曲线的平台","en":"The buffer region is the flat stretch of a titration curve"},"reason":{"zh":"弱酸被强碱滴定时，半等当点附近 HA 与 A⁻ 各占一半、pH = pKa，曲线最平——这段平台正是缓冲作用；库存耗尽，曲线就陡起来。","en":"When a weak acid is titrated with a strong base, near half-equivalence HA and A⁻ are equal, pH = pKa and the curve is flattest — that plateau is buffering at work; once the reserve runs out, the curve turns steep."},"source":"../chemistry/solutions/buffer-capacity/#step2"},
"clock-angles:unit-circle":{"type":"application","label":{"zh":"角度随时间匀速增长","en":"Angle grows steadily with time"},"reason":{"zh":"两根针都是绕圆心匀速转动，转过的角度与时间成正比，钟面就是一个带刻度的单位圆。","en":"Both hands turn about the centre at a constant rate, so angle is proportional to time and the dial is a graduated circle."},"source":"../math/geometry/clock-angles/#step0"},
"compound-interest:montecarlo":{"type":"connection","label":{"zh":"把确定的账换成随机的账","en":"From a certain ledger to a random one"},"reason":{"zh":"复利假设利率确定；真实回报有波动时，可以用大量随机抽样估计终值的分布，这是蒙特卡洛的典型用法。","en":"Compounding assumes a certain rate; when real returns fluctuate, many random draws can estimate the distribution of the final value, a typical use of Monte Carlo."},"source":"../investment/rates/compound-interest/#step4"},
"compound-interest:variance":{"type":"connection","label":{"zh":"风险让期望不等于全部","en":"Risk means the expected value is not everything"},"reason":{"zh":"确定利率下终值只有一个数；回报有波动时需要同时看平均和方差，同样的平均增长率下波动越大，复利终值越低。","en":"At a certain rate the final value is a single number; with fluctuating returns you need both the mean and the variance, and for the same average return more volatility lowers the compounded result."},"source":"../investment/rates/compound-interest/#step5"},
"confidence-interval:hypothesis-testing":{"type":"connection","label":{"zh":"区间与检验是一体两面","en":"Intervals and tests are two sides of one coin"},"reason":{"zh":"两者用同一个标准误：双侧 z 检验在 5% 水平拒绝 μ₀，恰好等于 μ₀ 落在 95% 置信区间之外。区间报告不确定的范围，p 值报告在原假设下有多意外。","en":"Both use the same standard error: a two-sided z-test rejects μ₀ at the 5% level exactly when μ₀ lies outside the 95% confidence interval. The interval reports the range of uncertainty; the p-value reports how surprising the data are under the null."},"source":"../probability/inference/statistical-inference/#step2"},
"convolution:gaussian":{"type":"connection","label":{"zh":"描述独立变量相加的分布","en":"describes distributions of independent sums"},"reason":{"zh":"独立随机变量之和的分布由卷积给出；反复相加后的正态近似需满足中心极限定理的条件。","en":"Convolution gives the distribution of a sum of independent random variables; a normal approximation after repeated sums requires central-limit conditions."},"source":"../probability/statistics/central-limit-theorem/#step5"},
"counting-permutations:bayes":{"type":"connection","label":{"zh":"频数表里的计数","en":"Counts in a frequency table"},"reason":{"zh":"贝叶斯公式的自然频数写法就是数“符合条件的人”占“满足条件的人”的比例，用的正是同样的计数思想。","en":"The natural-frequency form of Bayes’ rule counts the people who meet a condition as a share of those in a group, the same counting idea."},"source":"../probability/basics/counting-permutations/#step4"},
"counting-permutations:probability":{"type":"foundation","label":{"zh":"等可能时概率靠数","en":"With equally likely outcomes, probability is counting"},"reason":{"zh":"等可能结果下概率就是符合条件的方法数除以总方法数，所以排列组合是计算古典概率的基础。","en":"With equally likely outcomes, probability is favourable ways divided by total ways, so permutations and combinations underlie classical probability."},"source":"../probability/basics/counting-permutations/#step5"},
"cross-entropy:gradient-descent":{"type":"application","label":{"zh":"训练就是把交叉熵往下推","en":"Training pushes cross-entropy down"},"reason":{"zh":"分类模型把交叉熵当损失：它衡量模型分布 q 离数据分布 p 有多远，梯度下降沿它的下坡方向调整参数，让 q 越来越像 p。","en":"Classifiers use cross-entropy as their loss: it measures how far the model’s distribution q is from the data’s p, and gradient descent follows its downhill direction to make q resemble p."},"source":"../probability/stochastic/entropy/#step5"},
"decision-trees:estimate":{"type":"connection","label":{"zh":"深度与新数据表现","en":"depth and new-data performance"},"reason":{"zh":"树越深，训练准确率只升不降，但对没见过的数据的准确率在有噪声时会先升后降；这是固定数据集上的演示，不是普遍定律。","en":"Training accuracy only rises with depth, but accuracy on unseen data rises then falls when there is noise; this is a demonstration on one fixed data set, not a universal law."},"source":"../computing/ml/decision-trees/#step3"},
"derivative:titration-curves":{"type":"application","label":{"zh":"突跃就是斜率最大处","en":"The leap is where the slope peaks"},"reason":{"zh":"等当点处 dpH/dV 最大，所以判断终点就是找曲线斜率的峰。","en":"dpH/dV is largest at the equivalence point, so locating the end point means finding the peak of the curve's slope."},"source":"../chemistry/solutions/titration-curves/#step1"},
"diversification:risk-pooling":{"type":"connection","label":{"zh":"同样的 1/√N 直觉，机制不同","en":"The same 1/√N intuition, a different mechanism"},"reason":{"zh":"保险靠很多人各自独立出险，平均下来就稳；投资分散靠资产低相关。两者都是“平均能熨平波动”，但共同灾难和系统风险都会让波动停在一个下限。","en":"Insurance relies on many people’s claims being independent, so the average is steady; diversification relies on low correlation between assets. Both are “averaging smooths the wobble”, and in both a common catastrophe or systematic risk leaves a floor."},"source":"../investment/basics/diversification/#step3"},
"dna-replication:probability":{"type":"connection","label":{"zh":"基因的传递与遗传学","en":"Passing genes on"},"reason":{"zh":"基因传给后代的概率，根子在分子事件里：复制保真度、突变、染色体分离方式，决定了后代拿到哪个版本——概率页的数字，正是这些分子事件的统计结果。","en":"The odds of passing a gene to offspring are rooted in molecular events: copying fidelity, mutation and how chromosomes separate decide which version offspring get — the probability lesson's numbers are the statistics of those molecular events."},"source":"../biology/cells/dna-replication/#step1"},
"eigen:markov-chains":{"type":"connection","label":{"zh":"特征值决定收敛速度","en":"Eigenvalues set the convergence speed"},"reason":{"zh":"转移矩阵的稳态是特征值 1 对应的左特征向量，其余特征值的大小 |λ₂| 决定与稳态的距离按 |λ₂|ⁿ 衰减。","en":"The steady state is the left eigenvector for eigenvalue 1, and the size of the next eigenvalue |λ₂| makes the distance to it decay like |λ₂|ⁿ."},"source":"../probability/stochastic/markov-chains/#step4"},
"eigen:probability":{"type":"connection","label":{"zh":"稳态分布就是特征向量","en":"The steady distribution is an eigenvector"},"reason":{"zh":"稳态 π 满足 πP = π：它正是转移矩阵特征值 1 的特征向量；随机游走的长期比例，本质上是一个特征问题。","en":"The steady state π satisfies πP = π — it is exactly the eigenvector of the transition matrix for eigenvalue 1; a random walk's long-run shares are, at heart, an eigen-problem."},"source":"../probability/stochastic/markov-chains/#step4"},
"eigen:variance":{"type":"application","label":{"zh":"找出协方差主方向","en":"finds principal covariance directions"},"reason":{"zh":"对协方差矩阵，特征向量给出互相正交的主方向，特征值给出沿这些方向的方差。","en":"For a covariance matrix, an orthonormal eigenbasis gives principal directions, and eigenvalues give variances along them."},"source":"../math/linear-algebra/eigenvectors/#step5"},
"electrochemistry:probability":{"type":"connection","label":{"zh":"能斯特方程里的对数","en":"The logarithm in the Nernst equation"},"reason":{"zh":"能斯特方程的对数形式来自玻尔兹曼因子：浓度比改一个数量级，电压只动一个固定台阶——电压与 log Q 成直线，根子是概率的指数律。","en":"The Nernst equation's logarithmic form comes from the Boltzmann factor: change the concentration ratio by one order of magnitude and the voltage moves by one fixed step — voltage linear in log Q is rooted in probability's exponential law."},"source":"../chemistry/reactions/electrochemistry/#step2"},
"exp-log:information-entropy":{"type":"foundation","label":{"zh":"只有对数能让惊讶相加","en":"Only a logarithm makes surprise add up"},"reason":{"zh":"两个独立事件同时发生的概率相乘，信息量却应该相加；能把乘法变成加法的是对数，所以信息量取 −log p，以 2 为底时单位是比特。","en":"The probability of two independent events multiplies, yet their information should add; a logarithm is what turns products into sums, so information is −log p, measured in bits with base 2."},"source":"../probability/stochastic/entropy/#step1"},
"expected-value:montecarlo":{"type":"application","label":{"zh":"长期平均逼近期望","en":"Long-run averages approach it"},"reason":{"zh":"重复抽样的平均值按 σ/√n 逼近期望，蒙特卡洛估计就是用这个事实把平均值当作期望的估计。","en":"The average of repeated draws approaches the expectation with error about σ/√n, the fact Monte Carlo estimation uses to take the average as an estimate of the expectation."},"source":"../probability/basics/expected-value/#step2"},
"expected-value:signal-detection-theory":{"type":"application","label":{"zh":"按期望代价选判据","en":"Choose the criterion by expected cost"},"reason":{"zh":"每次试验的期望代价 = p·(1−H)·m + (1−p)·F·f；漏报越贵、信号越常见，代价最低的判据就越宽松——最好的判据不在正中间。","en":"The expected cost per trial is p·(1−H)·m + (1−p)·F·f; the costlier a miss and the commoner the signal, the more lenient the cheapest criterion — the best criterion is not in the middle."},"source":"../psychology/cognition/signal-detection/#step5"},
"expected-value:variance":{"type":"connection","label":{"zh":"期望之外还要看波动","en":"Beyond the mean, the spread"},"reason":{"zh":"保险与彩票的例子说明期望相同或更差时，波动（方差）仍会改变决定，所以期望和方差要一起看。","en":"The insurance and lottery examples show that with equal or worse expectation the spread (variance) can still change the decision, so expectation and variance go together."},"source":"../probability/basics/expected-value/#step4"},
"gaussian:confidence-interval":{"type":"foundation","label":{"zh":"样本均值近似正态","en":"Sample means are roughly normal"},"reason":{"zh":"中心极限定理让样本均值在 n 较大时近似正态、标准差为 σ/√n，所以才能用 ±1.96 个标准误围出 95% 的区间。","en":"The central limit theorem makes the sample mean roughly normal for large n, with standard deviation σ/√n, which is why ±1.96 standard errors bound a 95% interval."},"source":"../probability/inference/statistical-inference/#step0"},
"gaussian:probability":{"type":"representation","label":{"zh":"曲线高度就是概率密度","en":"Curve height is probability density"},"reason":{"zh":"正态曲线每点的高度是概率密度，曲线下面积等于概率——钟形本身就是一种概率分布的画像。","en":"At each point the normal curve's height is a probability density and area under it equals probability — the bell itself is a portrait of a probability distribution."},"source":"../probability/basics/binomial-normal/#step3"},
"gaussian:risk-pooling":{"type":"application","label":{"zh":"大池子的出险人数近似正态","en":"Claim counts in a big pool look normal"},"reason":{"zh":"第 2 步的二项分布在 N 大时呈钟形，破产概率就是钟形右尾的面积。","en":"Step 2’s binomial becomes bell-shaped for large N, and the ruin probability is the area of the bell’s right tail."},"source":"../probability/stochastic/risk-pooling/#step2"},
"gaussian:signal-detection-theory":{"type":"foundation","label":{"zh":"两条同宽的正态分布","en":"Two normal curves of equal width"},"reason":{"zh":"模型假设噪声和信号下的证据强度都是正态分布、宽度相同；d′ 就是两条钟形曲线的中心相距几个标准差，z(H) − z(F) 用标准正态把比例换回位置。","en":"The model assumes evidence strength is normally distributed, with equal width, both with and without the signal; d′ is how many standard deviations apart the two bell curves’ centres are, and z(H) − z(F) uses the standard normal to turn proportions back into positions."},"source":"../psychology/cognition/signal-detection/#step1"},
"hypothesis-testing:multiple-comparisons":{"type":"foundation","label":{"zh":"每次检验 5% 的误报","en":"Each test has a 5% false alarm"},"reason":{"zh":"第 4 章以假设检验的门槛为前提：零效应的一次检验有 5% 的机会“显著”，做 k 次至少一次显著的概率是 1 − 0.95^k，k = 20 时 64%。","en":"Chapter 4 builds on the hypothesis-test threshold: a single null test is “significant” 5% of the time, so k tests give at least one with probability 1 − 0.95^k, 64% at k = 20."},"source":"../probability/everyday/numbers-lie/#c4"},
"information-entropy:cross-entropy":{"type":"foundation","label":{"zh":"真熵是交叉熵的下限","en":"True entropy is the floor of cross-entropy"},"reason":{"zh":"用正确的分布标价，平均惊讶就是熵 H(p)；换成错误的 q 只会更贵：H(p, q) = H(p) + KL(p‖q)，多出的 KL 永远不小于 0。","en":"Priced with the true distribution, the average surprise is the entropy H(p); a wrong q can only cost more: H(p, q) = H(p) + KL(p‖q), and the extra KL is never negative."},"source":"../probability/stochastic/entropy/#step5"},
"information-entropy:decision-trees":{"type":"application","label":{"zh":"信息增益就是熵的下降","en":"Information gain is a drop in entropy"},"reason":{"zh":"决策树每一刀都选让子集平均熵下降最多的切法；这个下降量就是信息增益，用的正是同一个 H = −Σ p log₂ p。","en":"Each split in a decision tree picks the cut that lowers the subsets’ average entropy the most; that drop is the information gain, computed with the same H = −Σ p log₂ p."},"source":"../computing/ml/decision-trees/#step1"},
"information-entropy:predictive-compression-entropy":{"type":"foundation","label":{"zh":"每像素位数就是残差的熵","en":"Bits per pixel are the residual’s entropy"},"reason":{"zh":"第 6 章引用熵页的熵工坊与哈夫曼编码：能压多小取决于多好猜，预测残差的熵就是每像素至少要花的位数。","en":"Chapter 6 cites the entropy workshop and Huffman coding of the Entropy page: how small a file gets depends on how predictable it is, and the residual’s entropy is the bits per pixel it needs at least."},"source":"../tech/devices/inside-a-phone/#compress"},
"kalman:dead-reckoning-drift":{"type":"connection","label":{"zh":"预测与更新","en":"Predict and update"},"reason":{"zh":"第 2 章说明它用的“定位一到就重置”是最粗的融合，真实手机用卡尔曼滤波的预测与更新来合并积分与 GPS。","en":"Chapter 2 notes that resetting on each fix is the crudest fusion; real phones combine integration and GPS with the Kalman filter’s predict-and-update."},"source":"../tech/devices/inside-a-phone/#accel"},
"kalman:feedback":{"type":"application","label":{"zh":"提供用于控制的状态估计","en":"supplies state estimates for control"},"reason":{"zh":"无法直接观测的状态可先估计，再交给控制器；估计质量和模型误差会影响控制效果。","en":"Estimate states that cannot be measured directly, then pass them to a controller; estimation quality and model mismatch affect control."},"source":"../signal/control/kalman/#step6"},
"mean-median-mode:mean-vs-median-long-tail":{"type":"foundation","label":{"zh":"两种“平均”回答两个问题","en":"Two averages, two questions"},"reason":{"zh":"第 8 章引用平均数、中位数、众数之争的第 1 步：平均数回答“平分每人多少”，中位数回答“普通人什么样”；长尾分布里两者分开，σ = 1 时平均是中位的 1.65 倍。","en":"Chapter 8 cites step 1 of Mean, Median, Mode: the mean answers “how much each if shared”, the median “what a typical person has”; in a long tail they separate, the mean being 1.65 times the median at σ = 1."},"source":"../probability/everyday/numbers-lie/#c8"},
"mean-median-mode:variance":{"type":"connection","label":{"zh":"中心之外还要看散布","en":"Spread matters as well as centre"},"reason":{"zh":"三个“平均”都只描述中心位置；极端值造成的差别说明还需要方差一类的量来描述数据散得多开。","en":"All three “averages” describe only the centre; the gaps an extreme value creates show we also need a measure such as variance to say how spread out the data are."},"source":"../probability/statistics/mean-median-mode/#step1"},
"meiosis:mendelian-inheritance":{"type":"foundation","label":{"zh":"配子只带一份等位基因","en":"Each gamete carries one allele"},"reason":{"zh":"减数分裂让同源染色体分开，每个配子只得到一对等位基因中的一个；Punnett 方格边上每种配子各占 1/2 就是这么来的。","en":"Meiosis separates homologous chromosomes so each gamete receives just one allele of each pair; that is where the 1/2 for each gamete on the edge of the Punnett square comes from."},"source":"../probability/basics/genetics-probability/#step0"},
"montecarlo:auctions":{"type":"application","label":{"zh":"用随机抽样验证收益相等","en":"Simulation checks revenue equivalence"},"reason":{"zh":"多轮随机抽取估值并累计平均，两种规则的平均收益靠近同一个理论值，这是蒙特卡洛估计的直接应用。","en":"Drawing values at random over many rounds and averaging brings both rules to the same theoretical value, a direct use of Monte Carlo estimation."},"source":"../math/applied/auction-basics/#step2"},
"montecarlo:bandit-arms":{"type":"application","label":{"zh":"用样本估计，并量化不确定性","en":"estimate from samples and quantify uncertainty"},"reason":{"zh":"每台机器的中奖率只能用有限次抽样估计，次数越少误差范围越宽；探索策略正是围绕这种估计误差设计的。","en":"Each machine's win rate can only be estimated from finitely many draws, with a wider error range for fewer draws; exploration strategies are designed around exactly this estimation error."},"source":"../probability/stochastic/bandit-arms/#step0"},
"montecarlo:dna-replication":{"type":"connection","label":{"zh":"随机变异","en":"Random variation"},"reason":{"zh":"突变是随机事件：要估计一群基因里出现某种突变的比例，就得像蒙特卡洛那样大量随机抽样、数出频率——突变页的“随机”正是抽样估计的对象。","en":"Mutations are random events: to estimate how often a given mutation shows up in a population of genes, you sample at random many times and count the frequency, Monte Carlo style — the replication lesson's 'random' is exactly what sampling estimates."},"source":"../biology/cells/dna-replication/#step4"},
"montecarlo:kinetic-theory":{"type":"connection","label":{"zh":"统计涨落随样本变小","en":"Fluctuations shrink with sample size"},"reason":{"zh":"压强读数的涨落随撞墙次数增多而变小，与蒙特卡洛的 1/√n 同类。","en":"Pressure readings fluctuate less as wall hits accumulate, the same 1/√n behaviour as Monte Carlo estimates."},"source":"../physics/thermal/kinetic-theory/#step0"},
"montecarlo:meiosis":{"type":"connection","label":{"zh":"累积随机抽样看分布","en":"Tallying random draws to see a distribution"},"reason":{"zh":"页面反复随机做减数分裂并累积计数，次数越多各种配子的比例越接近期望，与蒙特卡洛同一思路。","en":"The page repeatedly runs random meioses and tallies them; the more draws, the closer the shares are to expectation, the Monte Carlo idea."},"source":"../biology/cells/meiosis/#step3"},
"natural-selection:antibiotic-selection-window":{"type":"application","label":{"zh":"病人体内的自然选择","en":"Natural selection inside a patient"},"reason":{"zh":"第 8 章说抗生素浓度在“挑选”细菌：中等浓度杀死敏感菌、留下耐药菌，正是自然选择在一次疗程里的样子。","en":"Chapter 8 says the antibiotic level selects bacteria: a middling level kills sensitive cells and leaves resistant ones, natural selection within one course of treatment."},"source":"../biology/body/body-in-balance/#ch8"},
"natural-selection:feedback":{"type":"connection","label":{"zh":"环境反过来塑造种群","en":"The environment shapes the population"},"reason":{"zh":"选择让种群跟随环境变化，但响应有滞后，是一阶系统跟随输入的生物版本。","en":"Selection makes the population follow the environment with a lag, a biological counterpart of a first-order system following an input."},"source":"../biology/ecology/natural-selection/#step3"},
"overfitting:decision-trees":{"type":"connection","label":{"zh":"同样的模式出现在树上","en":"the same pattern appears in trees"},"reason":{"zh":"决策树的深度和多项式的次数都是灵活度旋钮：灵活度越高，训练准确率越好，而新数据上的表现在有噪声时先升后降。","en":"Tree depth and polynomial degree are both flexibility knobs: higher flexibility improves training performance, while performance on new data rises then falls when there is noise."},"source":"../computing/ml/overfitting/#step1"},
"periodic-trends:gaussian":{"type":"connection","label":{"zh":"趋势与例外并存","en":"Trend with scatter"},"reason":{"zh":"趋势线是总体规律，真实数据点绕着它上下散开——这团散开的残差，正态分布就是描述它的标准形状。","en":"The trend line is the overall rule, and real data points scatter around it — that scattered cloud of residuals is exactly what the normal distribution is the standard shape for."},"source":"../chemistry/matter/periodic-trends/#step2"},
"poisson-process:montecarlo":{"type":"connection","label":{"zh":"模拟与理论互相检验","en":"Simulation and theory check each other"},"reason":{"zh":"本页每个模拟都用种子生成并与理论曲线对照，是蒙特卡洛“用模拟检验公式”的又一例。","en":"Each simulation here is seeded and compared with the theory curve, another case of Monte Carlo checking a formula."},"source":"../probability/stochastic/poisson-process/#step5"},
"poisson-process:shot-noise-frame-stacking":{"type":"foundation","label":{"zh":"光子数服从泊松分布","en":"Photon counts are Poisson"},"reason":{"zh":"第 4 章引用泊松过程里窗口中的到达个数：光子随机到达，数到 N 个时涨落约 √N，所以暗处每像素光子少、噪声比例大。","en":"Chapter 4 cites the arrivals-in-a-window step of the Poisson Process: photons arrive at random, so counting N of them fluctuates by about √N, and dim pixels with few photons are noisy."},"source":"../tech/devices/inside-a-phone/#camera"},
"positive-predictive-value:base-rate-neglect":{"type":"connection","label":{"zh":"同一个分母","en":"The same denominator"},"reason":{"zh":"第 6 章的一万人方格和贝叶斯诊断页的频数树算的是同一个量：阳性里真有病的比例；患病率 1%、误报 5% 时只有 15.4%。","en":"Chapter 6’s grid of 10,000 people and the Bayes Diagnostics frequency tree compute the same quantity, the share of positives who are ill: 15.4% at 1% prevalence and 5% false positives."},"source":"../probability/everyday/numbers-lie/#c6"},
"positive-predictive-value:signal-detection-theory":{"type":"connection","label":{"zh":"同一张四格表","en":"The same four-cell table"},"reason":{"zh":"诊断的真阳性、假阴性、假阳性、真阴性，就是信号检测论里的命中、漏报、虚报、正确拒绝：灵敏度是命中率，1 − 特异度是虚报率。","en":"A test’s true positives, false negatives, false positives and true negatives are signal detection’s hits, misses, false alarms and correct rejections: sensitivity is the hit rate and 1 − specificity the false-alarm rate."},"source":"../probability/inference/bayes-diagnostics/#step-likelihood"},
"prisoners-dilemma:natural-selection":{"type":"connection","label":{"zh":"得分决定谁被复制","en":"Score decides who is copied"},"reason":{"zh":"第 4 步的复制者动态让得分高的策略比例上升，与自然选择“适合度高者占比增加”是同一种数学。","en":"Step 4’s replicator dynamics let higher-scoring strategies grow in share, the same mathematics as fitter types increasing under natural selection."},"source":"../math/applied/prisoners-dilemma/#step4"},
"probability-distribution:gaussian":{"type":"representation","label":{"zh":"条形变细变多，趋向钟形曲线","en":"Finer, more numerous bars tend toward the bell curve"},"reason":{"zh":"对称预设的条形已经是钟形；把条形变细、变多，离散的分布就趋向连续的高斯曲线——同一随机现象，两种表示。","en":"The symmetric preset's bars already form a bell; make the bars finer and more numerous and the discrete distribution tends toward the continuous Gaussian curve — one phenomenon, two representations."},"source":"../probability/basics/probability-distribution/#step0"},
"probability-distribution:variance":{"type":"application","label":{"zh":"方差就是从分布里算出来的离散程度","en":"Variance is the spread computed from the distribution"},"reason":{"zh":"方差不是凭空来的数：拿分布的每根条形，按概率加权平均它离重心的平方距离，就得到方差。","en":"Variance is not a number from nowhere: take every bar of the distribution, average its squared distance from the balance point weighted by probability, and you get variance."},"source":"../probability/basics/probability-distribution/#step2"},
"probability-vs-frequency:confidence-interval":{"type":"foundation","label":{"zh":"频率的波动范围就是区间","en":"The spread of a frequency is an interval"},"reason":{"zh":"转 n 次时，频率约有 95% 的机会落在 p ± 1.96√(p(1−p)/n) 之内；把这个范围反过来套在观测到的频率上，就是比例的置信区间。","en":"With n spins the frequency lands within p ± 1.96√(p(1−p)/n) about 95% of the time; turning that band around the observed frequency gives a confidence interval for a proportion."},"source":"../probability/basics/probability-frequency/#step5"},
"probability-vs-frequency:montecarlo":{"type":"foundation","label":{"zh":"用频率去估计","en":"Estimating with frequencies"},"reason":{"zh":"频率随次数增加收拢到概率，蒙特卡洛正是反过来利用这一点：用大量随机试验的频率或平均值去估计概率、面积和期望，误差随 1/√n 缩小。","en":"Because frequencies close in on probabilities as trials grow, Monte Carlo runs the idea backwards: it estimates probabilities, areas and expectations from the frequencies or averages of many random trials, with error shrinking like 1/√n."},"source":"../probability/basics/probability-frequency/#step2"},
"probability-vs-frequency:probability":{"type":"foundation","label":{"zh":"频率给概率一个可检验的意思","en":"Frequency gives probability a testable meaning"},"reason":{"zh":"单次结果说不准，但大量重复后频率会稳定在概率附近；概率模型说的正是这种长期频率，也因此能拿实验数据去检验。","en":"A single outcome cannot be predicted, but over many repeats the frequency settles near the probability; a probability model speaks about exactly this long-run frequency, which is why it can be checked against data."},"source":"../probability/basics/probability-frequency/#step1"},
"probability-vs-frequency:quantum-amplitude":{"type":"foundation","label":{"zh":"单次随机，多次见概率","en":"One shot is random; many shots reveal the probability"},"reason":{"zh":"单次测量的结果无法预测，只有重复很多次，样本比例才贴近振幅平方给出的概率——这正是概率与频率页讲的频率稳定性。","en":"A single measurement cannot be predicted; only over many repeats does the sample fraction settle near the probability given by the squared amplitude — the stability of frequencies taught in the probability-and-frequency lesson."},"source":"../physics/modern/quantum-basics/#step1"},
"probability-vs-frequency:small-sample-variability":{"type":"foundation","label":{"zh":"次数越多越稳","en":"More trials, steadier frequency"},"reason":{"zh":"第 2 章引用概率与频率的第 2 步：样本越大，频率越贴近概率；反过来，小样本的平均数摆动更大，标准误是 10/√n。","en":"Chapter 2 cites step 2 of Probability & Frequency: the larger the sample, the closer the frequency to the probability; conversely a small sample’s average swings more, with standard error 10/√n."},"source":"../probability/everyday/numbers-lie/#c2"},
"probability:activation-energy":{"type":"application","label":{"zh":"分子能量的概率","en":"A probability over molecular energies"},"reason":{"zh":"能量足够的分子比例就是一个概率 e^(−Eₐ/RT)，速率常数把这个概率乘上碰撞频率。","en":"The fraction of molecules with enough energy is a probability, e^(−Eₐ/RT), and the rate constant multiplies it by a collision frequency."},"source":"../chemistry/reactions/activation-energy/#step2"},
"probability:attention-mechanism":{"type":"connection","label":{"zh":"softmax 权重像一个分布","en":"softmax weights behave like a distribution"},"reason":{"zh":"softmax 输出非负且和为 1，可以读成「看每个词的比例」，熵衡量它有多集中；这是比喻性的读法，并非真实概率。","en":"Softmax outputs are non-negative and sum to 1, so they can be read as proportions of attention, with entropy measuring how concentrated they are; this is a reading aid, not a literal probability."},"source":"../computing/ml/attention-mechanism/#step1"},
"probability:bayes":{"type":"foundation","label":{"zh":"为证据更新提供模型","en":"provides a model for evidence updates"},"reason":{"zh":"先验和似然都来自概率模型；贝叶斯公式将它们结合成给定观测后的条件概率。","en":"The prior and likelihood come from a probability model; Bayes’ rule combines them into a probability conditional on observations."},"source":"../probability/inference/bayes-updating/#step1"},
"probability:binomial-normal":{"type":"foundation","label":{"zh":"重复独立试验的计数","en":"Counting repeated independent trials"},"reason":{"zh":"概率的乘法规则加上路径计数，给出 n 次独立试验恰好成功 k 次的概率。","en":"The multiplication rule for probabilities plus path counting gives the chance of exactly k successes in n independent trials."},"source":"../probability/basics/binomial-normal/#step0"},
"probability:decision-trees":{"type":"application","label":{"zh":"用类别比例算熵","en":"entropy from class proportions"},"reason":{"zh":"每个区域里各类所占的比例构成一个概率分布，熵衡量它有多混；信息增益就是切分前后熵的减少量。","en":"The class shares in a region form a probability distribution and entropy measures how mixed it is; information gain is the drop in entropy caused by a cut."},"source":"../computing/ml/decision-trees/#step0"},
"probability:expected-value":{"type":"foundation","label":{"zh":"概率加权平均","en":"A probability-weighted average"},"reason":{"zh":"有了每个结果的概率，才能按概率加权算出长期平均——期望就是这张概率表的加权平均数，是“平均会怎样”的第一个数字。","en":"Once each outcome has a probability, weighting by those probabilities gives the long-run average — the expected value is that probability table's weighted average, the first number answering 'what happens on average'."},"source":"../probability/basics/expected-value/#step0"},
"probability:hypothesis-testing":{"type":"application","label":{"zh":"用概率分布判断“是否太罕见”","en":"Using a distribution to judge “too rare”"},"reason":{"zh":"检验把“如果硬币公平，这个结果有多罕见”换成一个由二项分布算出的概率，这是概率分布在推断上的直接应用。","en":"A test turns “how rare would this result be if the coin were fair” into a probability computed from the binomial distribution, a direct use of probability distributions in inference."},"source":"../probability/inference/hypothesis-testing/#step0"},
"probability:information-entropy":{"type":"foundation","label":{"zh":"把概率换成惊讶再平均","en":"Turn probabilities into surprise, then average"},"reason":{"zh":"熵是对每种结果的惊讶 −log₂ p 按其概率加权平均：分布越均匀越难猜、熵越大，几乎必然的分布熵接近 0。","en":"Entropy weights each outcome’s surprise −log₂ p by its probability: the more even the distribution, the harder it is to guess and the larger the entropy; a near-certain one has entropy near zero."},"source":"../probability/stochastic/entropy/#step2"},
"probability:isomers":{"type":"application","label":{"zh":"计数与组合","en":"Counting and combinatorics"},"reason":{"zh":"骨架计数是组合问题：先生成所有可能，再用规范形式去重。","en":"Counting skeletons is a combinatorics problem: generate every possibility, then remove repeats with a canonical form."},"source":"../chemistry/matter/isomers/#step1"},
"probability:kinetic-theory":{"type":"connection","label":{"zh":"速率分布来自随机碰撞","en":"Random collisions shape the speed distribution"},"reason":{"zh":"大量粒子的随机碰撞让速率分布趋向固定形状，个别粒子不可预测。","en":"Random collisions among many particles drive the speed distribution to a fixed shape while single particles stay unpredictable."},"source":"../physics/thermal/kinetic-theory/#step3"},
"probability:llm-sampling":{"type":"application","label":{"zh":"概率分布与抽样","en":"distributions and sampling"},"reason":{"zh":"逐词生成就是反复从一个离散概率分布中抽样；抽得越多，频率越接近该分布。","en":"Generating word by word is repeated sampling from a discrete probability distribution; the more draws, the closer the frequencies get to it."},"source":"../computing/ml/llm-sampling/#step3"},
"probability:markov-chains":{"type":"application","label":{"zh":"条件概率链起来","en":"Conditional probabilities chained together"},"reason":{"zh":"转移概率就是“已知今天、明天各状态的条件概率”，把它们一步步相乘相加就得到多步转移。","en":"A transition probability is the conditional probability of each state tomorrow given today, and multiplying and adding them step by step gives multi-step transitions."},"source":"../probability/stochastic/markov-chains/#step0"},
"probability:meiosis":{"type":"application","label":{"zh":"独立随机事件的组合","en":"Combining independent random events"},"reason":{"zh":"每对染色体独立地随机取向，n 对的组合数是 2ⁿ，配子的分布由计数得到。","en":"Each pair aligns independently at random, so n pairs give 2ⁿ combinations and the gamete distribution follows from counting."},"source":"../biology/cells/meiosis/#step2"},
"probability:mendelian-inheritance":{"type":"application","label":{"zh":"独立事件概率相乘","en":"Independent events multiply"},"reason":{"zh":"父母双方的配子独立结合，两对基因又独立分配，所以概率可以相乘：1/2 × 1/2 得 1/4，3/4 × 3/4 得 9/16。","en":"The two parents’ gametes combine independently and the two genes assort independently, so the probabilities multiply: 1/2 × 1/2 gives 1/4, and 3/4 × 3/4 gives 9/16."},"source":"../probability/basics/genetics-probability/#step2"},
"probability:montecarlo":{"type":"application","label":{"zh":"用随机采样估计期望","en":"estimates expectations by random sampling"},"reason":{"zh":"按指定概率模型采样，用样本平均估计期望；积分也可改写成相应的期望。","en":"Sample from a specified probability model and average to estimate an expectation; integrals can also be written as expectations."},"source":"../probability/stochastic/monte-carlo/#step3"},
"probability:natural-selection":{"type":"application","label":{"zh":"存活是概率事件","en":"Survival is a chance event"},"reason":{"zh":"每只蛾以概率 w 存活，种群比例是大量随机事件的平均，小种群里随机性很明显。","en":"Each moth survives with probability w, and the population share is an average of many random events, with chance clearly visible in small populations."},"source":"../biology/ecology/natural-selection/#step0"},
"probability:pagerank":{"type":"application","label":{"zh":"随机游走的长期频率","en":"long-run frequency of a random walk"},"reason":{"zh":"随机冲浪者每一步按概率选下一页，长期访问频率收敛到一个分布，这个分布就是 PageRank。","en":"A random surfer picks the next page by probability at each step, and the long-run visit frequencies converge to a distribution: the PageRank."},"source":"../computing/algorithms/pagerank/#step1"},
"probability:poisson-process":{"type":"application","label":{"zh":"用分布描述随机到达","en":"Distributions describing random arrivals"},"reason":{"zh":"第 2 步把“窗口里到了几个”这个随机变量的分布写成泊松分布，并用平均与方差检验。","en":"Step 2 writes the distribution of “how many arrivals in a window” as a Poisson distribution and tests it with mean and variance."},"source":"../probability/stochastic/poisson-process/#step2"},
"probability:probability-distribution":{"type":"foundation","label":{"zh":"概率排成条形就是分布","en":"Probabilities lined up are a distribution"},"reason":{"zh":"每个结果的概率就是一根条形的高度，全部条形加起来等于 1——分布不是新概念，是把概率按结果排成的形状。","en":"Each outcome's probability is one bar's height, and all bars sum to 1 — a distribution is not a new idea, it is probabilities arranged by outcome."},"source":"../probability/basics/probability-distribution/#step0"},
"probability:variance":{"type":"foundation","label":{"zh":"同一组概率既定均值也定波动","en":"The same probabilities set both mean and spread"},"reason":{"zh":"方差 E[(X−μ)²] 用的正是同一组概率作权重：期望只报平均位置，方差补报分布有多散，两者是同一张概率表的两栏。","en":"Variance E[(X−μ)²] weights with exactly the same probabilities: expectation reports only the average position, variance adds how scattered the distribution is — two columns of the same probability table."},"source":"../probability/basics/expected-value/#step4"},
"regression-correlation:diversification":{"type":"foundation","label":{"zh":"ρ 从 1 到 −1","en":"ρ from 1 to −1"},"reason":{"zh":"等权两只资产时组合波动是 σ·√((1+ρ)/2)：ρ = 1 不降，ρ = 0 降到约 0.71 倍，ρ = −1 完全抵消——相关系数就是“是否一起动”的那个数。","en":"With two equal-weight assets the portfolio volatility is σ·√((1+ρ)/2): no reduction at ρ = 1, down to about 0.71 times at ρ = 0, fully cancelled at ρ = −1 — the correlation coefficient is the number for “moving together”."},"source":"../investment/basics/diversification/#step1"},
"regression-correlation:regression-to-the-mean":{"type":"foundation","label":{"zh":"回归线斜率小于 1","en":"A regression slope below 1"},"reason":{"zh":"第 1 章把读者引到回归与相关的第 5 步：父母和孩子的身高之所以“回归”，是因为两次测量只部分相关，这也是第一次考试的极端者第二次向平均靠拢的原因。","en":"Chapter 1 sends the reader to step 5 of Regression & Correlation: parents’ and children’s heights “regress” because the two measurements are only partly correlated, the same reason first-test extremes move toward the mean."},"source":"../probability/everyday/numbers-lie/#c1"},
"regression-correlation:simpsons-paradox":{"type":"connection","label":{"zh":"混杂：散点版与表格版","en":"Confounding, scatter and table"},"reason":{"zh":"第 5 章把辛普森悖论讲成混杂因素在表格里的样子，并把散点版的混杂（冰淇淋与溺水）交给回归与相关的第 3 步。","en":"Chapter 5 presents Simpson’s paradox as confounding seen in a table and leaves the scatter-plot version (ice cream and drowning) to step 3 of Regression & Correlation."},"source":"../probability/everyday/numbers-lie/#c5"},
"regression-correlation:slope":{"type":"application","label":{"zh":"用斜率读出变化关系","en":"Reading a relation off a slope"},"reason":{"zh":"第 1 步的拟合斜率 m 就是“x 增加 1，y 平均增加多少”，是直线斜率概念在数据上的应用。","en":"The fitted slope m in step 1 is “how much y rises on average per unit of x”, the straight-line slope applied to data."},"source":"../probability/statistics/regression-correlation/#step1"},
"regression-to-the-mean:multiple-comparisons":{"type":"connection","label":{"zh":"重做显著的那几项","en":"Re-run the significant ones"},"reason":{"zh":"第 1–4 章共用一个检验：在新数据上再看一次。按第 4 章的“重做显著的那几项”，靠运气显著的结果大多不再显著，和第 1 章的极端分数回到平均是同一件事。","en":"Chapters 1–4 share one check, look again on new data. Re-running chapter 4’s significant results makes most of them non-significant, the same thing as chapter 1’s extreme scores returning to average."},"source":"../probability/everyday/numbers-lie/#c4"},
"regression-to-the-mean:small-sample-variability":{"type":"foundation","label":{"zh":"再看一年：前 10 名落回中间","en":"Another year: last year’s top 10 fall back"},"reason":{"zh":"第 2 章的“下一年”按钮复用第 1 章的回归：小学校的极端平均数多半来自运气，换一年运气，上一年的前 10 名平均排到第 205 名左右。","en":"Chapter 2’s “next year” button reuses chapter 1’s regression: a small school’s extreme average is mostly luck, so with fresh luck last year’s top 10 land around 205th of 400."},"source":"../probability/everyday/numbers-lie/#c2"},
"regression-to-the-mean:survivorship-bias":{"type":"foundation","label":{"zh":"幸存者的下一个五年回到平均","en":"Survivors’ next five years return to average"},"reason":{"zh":"第 3 章“再看五年”复用第 1 章的回归：被挑出来的幸存基金此后五年年化约 4.5%，接近所有基金的 4%，远低于宣传册上的 5.8%。","en":"Chapter 3’s “five more years” reuses chapter 1’s regression: the selected surviving funds earn about 4.5% a year over the next five years, close to the 4% of all funds and far below the brochure’s 5.8%."},"source":"../probability/everyday/numbers-lie/#c3"},
"relative-vs-absolute-risk:vaccine-efficacy-relative-risk":{"type":"connection","label":{"zh":"相对风险与绝对风险","en":"Relative and absolute risk"},"reason":{"zh":"第 4 章说一个效力数字漏掉了绝对风险：试验里每 10,000 人只少病约 84 例，约 119 人接种防一例；两者的区别见“数字没有说谎，结论却错了”第 7 章。","en":"Chapter 4 notes that one efficacy number leaves out absolute risk: the trial prevented about 84 cases per 10,000, about 119 vaccinated per case prevented; the difference is chapter 7 of Every Number Was True."},"source":"../biology/body/how-vaccines-work/#ch4"},
"signal-detection-theory:handover-hysteresis":{"type":"connection","label":{"zh":"判据的取舍","en":"Choosing a criterion"},"reason":{"zh":"第 9 章引用信号检测里判据的取舍：切换余量设低，噪声引起乒乓切换；设高，切换来得太晚，和检测判据的漏报与误报之争相同。","en":"Chapter 9 cites choosing a criterion in signal detection: a low handover margin lets noise cause ping-pong handovers, a high one makes them late, the same trade-off as misses against false alarms."},"source":"../tech/devices/inside-a-phone/#handover"},
"signal-detection-theory:hypothesis-testing":{"type":"connection","label":{"zh":"虚报就是第一类错误","en":"A false alarm is a Type I error"},"reason":{"zh":"统计检验也是在噪声里判断有没有效应：显著性水平 α 对应虚报率，检验力对应命中率；收紧判据少犯一种错，就得多犯另一种。","en":"A statistical test also decides whether an effect stands out from noise: the significance level α plays the false-alarm rate and the power the hit rate; tightening the criterion to make one error rarer makes the other more common."},"source":"../probability/inference/hypothesis-testing/#step2"},
"slope:density":{"type":"representation","label":{"zh":"斜率即密度","en":"Slope is density"},"reason":{"zh":"在质量—体积图上，同种材料的点落在过原点的直线上，这条直线的斜率 m/V 就是密度。","en":"On a mass–volume graph, points of one material fall on a line through the origin, and the slope m/V of that line is the density."},"source":"../physics/matter/density/#step1"},
"titration-curves:estimate":{"type":"application","label":{"zh":"用终点读数估算浓度","en":"Estimating a concentration from the end point"},"reason":{"zh":"酸浓度不是直接读出来的，是拿碱的浓度与体积算出来的——终点判得偏一点，算出的浓度就偏一点，所以滴定结果天生是个带误差的估计。","en":"An acid concentration is never read off directly; it is computed from the base's concentration and volume — judge the end point a little off and the computed concentration shifts by that much, so a titration result is by nature an estimate carrying error."},"source":"../chemistry/solutions/titration-curves/#step4"},
"variance:diversification":{"type":"foundation","label":{"zh":"组合的方差公式","en":"The portfolio variance formula"},"reason":{"zh":"两只资产组合的波动 σₚ = √(w₁²σ₁² + w₂²σ₂² + 2w₁w₂ρσ₁σ₂)：交叉项里有相关系数 ρ，正是它决定组合能抵消掉多少波动。","en":"A two-asset portfolio’s volatility is σₚ = √(w₁²σ₁² + w₂²σ₂² + 2w₁w₂ρσ₁σ₂): the cross term carries the correlation ρ, which decides how much wobble the mix cancels."},"source":"../investment/basics/diversification/#step1"},
"variance:gaussian":{"type":"foundation","label":{"zh":"决定均值的标准误差","en":"sets the standard error of a mean"},"reason":{"zh":"独立同分布的单个观测总体方差为 σ² 时，n 个样本的均值方差为 σ²/n；正态近似还需要适用的极限定理条件。","en":"For iid observations each having population variance σ², the mean of n samples has variance σ²/n; a normal approximation additionally needs appropriate limit-theorem conditions."},"source":"../probability/statistics/central-limit-theorem/#step3"},
"variance:kalman":{"type":"application","label":{"zh":"参与测量权重计算","en":"helps determine measurement weights"},"reason":{"zh":"预测不确定性与测量噪声共同决定增益；模型给出的不确定性必须与真实估计误差区分。","en":"Predicted uncertainty and measurement noise jointly determine the gain; model uncertainty must be distinguished from actual estimation error."},"source":"../signal/control/kalman/#step2"},
"variance:montecarlo":{"type":"connection","label":{"zh":"决定估计误差尺度","en":"sets the estimation error scale"},"reason":{"zh":"独立同分布且方差有限时，样本平均的标准误差按 1/√n 缩小；这是误差尺度，不是每次运行的保证。","en":"For iid samples with finite variance, the sample mean’s standard error scales as 1/√n; this is an error scale, not a guarantee for each run."},"source":"../probability/stochastic/monte-carlo/#step2"},
"variance:natural-selection":{"type":"connection","label":{"zh":"抽样方差 p(1−p)/N","en":"Sampling variance p(1−p)/N"},"reason":{"zh":"遗传漂变的大小由单代抽样方差 p(1−p)/N 累积而来，种群越小越大。","en":"The size of drift builds up from the one-generation sampling variance p(1−p)/N, larger for smaller populations."},"source":"../biology/ecology/natural-selection/#step4"},
"variance:overfitting":{"type":"application","label":{"zh":"换批数据的散布就是方差","en":"scatter across batches is variance"},"reason":{"zh":"高次多项式在不同训练批上拟合出差别很大的曲线，这种随样本而变的散布正是方差；偏差则是平均拟合偏离真实曲线的部分。","en":"A high-degree polynomial fitted to different training batches gives very different curves; that sample-to-sample scatter is the variance, while bias is how far the average fit sits from the true curve."},"source":"../computing/ml/overfitting/#step3"},
"variance:regression-correlation":{"type":"foundation","label":{"zh":"r 是归一化的协方差","en":"r is a normalised covariance"},"reason":{"zh":"第 0 步把偏离乘积按各自的波动幅度（方差的平方根）归一化得到 r，是方差概念的双变量推广。","en":"Step 0 scales the product of deviations by each quantity’s spread (the square root of variance) to get r, a two-variable extension of variance."},"source":"../probability/statistics/regression-correlation/#step0"},
"variance:risk-pooling":{"type":"application","label":{"zh":"人均损失的方差按 1/N 缩小","en":"Variance of the average shrinks as 1/N"},"reason":{"zh":"第 1 步直接用独立随机变量之和的方差公式：N 个独立损失的平均，方差为单个的 1/N。","en":"Step 1 applies the variance of a sum of independent random variables directly: the average of N independent losses has 1/N of one loss’s variance."},"source":"../probability/stochastic/risk-pooling/#step1"},
"variance:risk-return":{"type":"foundation","label":{"zh":"用方差量风险","en":"Variance measures risk"},"reason":{"zh":"两种投资平均都是 5%，一个挤在 5% 附近，一个铺到 −10% 到 +20%；方差量的就是结果离平均有多散——散开意味着可能更好，也可能更糟。","en":"Two investments both average 5%, one clustered near 5% and one spread from −10% to +20%; variance measures how scattered the results are around the average — scattered means possibly better, and possibly worse."},"source":"../investment/basics/risk-return/#step1"},
"variance:shot-noise-frame-stacking":{"type":"foundation","label":{"zh":"叠加 n 帧，噪声降 √n","en":"Stack n frames, noise falls by √n"},"reason":{"zh":"第 4 章引用中心极限定理的精度代价：叠加 16 帧把单帧 39.5% 的噪声降到 9.9%，像素边长加倍等于叠 4 帧。","en":"Chapter 4 cites the precision cost in the Central Limit Theorem: stacking 16 frames cuts single-frame noise of 39.5% to 9.9%, and doubling the pixel side equals stacking 4 frames."},"source":"../tech/devices/inside-a-phone/#camera"},
"working-memory-attention:signal-detection-theory":{"type":"connection","label":{"zh":"目标是信号，干扰物与它争道","en":"Targets are signal, distractors compete"},"reason":{"zh":"本页把注意当作带宽有限的通道：目标是要找的信号，干扰物同时涌入，干扰越多命中率越低。信号检测论是继续读这类任务的标准方法：它把“分不分得开”（d′）与“多愿意说有”（判据 c）分开，本页的模型只画出前一种方向。","en":"The page treats attention as a limited channel: targets are the signal you look for, distractors arrive alongside them, and hits fall as distractors rise. Signal detection theory is the standard way to read such a task further: it separates how well targets can be told apart (d′) from how readily one says “yes” (criterion c); the page models only the first."},"source":"../psychology/cognition/memory-attention/#step1"}
}});
